use vstd::prelude::*;

verus! {
    fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
        ensures
            result.len() == m.len(),
            forall |i: nat| 0 <= i < m.len() ==> result[i] == m[(m.len() - 1 - i) as usize],
    {
        let n = m.len();
        let mut result: Vec<f32> = Vec::new();
        result.resize(n, 0.0); // Initialize result with the same length as m

        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                result.len() == n,
                forall |j: nat| 0 <= j < i ==> result[j] == m[(n - 1 - j) as usize],
            decreases n - i,
        {
            result[i] = m[(n - 1 - i) as usize];
            i = i + 1;
        }
        result
    }
}
